 for a in axs:a.legend(fontsize=7,ncol=4);a.grid(alpha=.2)
 fig.suptitle('Study158 nominal — full original native forces and swept intervals');fig.tight_layout();fig.savefig(D/'plots/physics.png',dpi=150);plt.close(fig)

